const ALIASES: Record<string, string> = {
  // College Scorecard name -> cheat-sheet name (both pre-normalized)
  "pennsylvania state university": "penn state university park",
};
const norm = (s: string) => {
  const n = s.toLowerCase().replace(/[^a-z0-9 ]/g, " ").replace(/\b(the|of|at|and)\b/g, " ")
    .replace(/\bmain campus\b/g, " ").replace(/\s+/g, " ").trim();
  return ALIASES[n] ?? n;
};

let index: Map<string, DisplacementEntry> | null = null;
export function lookupDisplacement(collegeName: string): DisplacementEntry | null {
  if (!index) {
    index = new Map();
    for (const e of DISPLACEMENT_DATA) index.set(norm(e.n), e);
  }
  return index.get(norm(collegeName)) ?? null;
}
